/* ââ ÐÐ²ÑÐ¾-ÑÐ¶Ð°ÑÐ¸Ðµ Ð²Ð¸Ð´ÐµÐ¾ Ð¿ÑÐ¸ Ð·Ð°Ð³ÑÑÐ·ÐºÐµ ÐºÑÐµÐ°ÑÐ¸Ð²Ð° (ffmpeg â mp4/H.264, ÑÐ¾Ð²Ð¼ÐµÑÑÐ¸Ð¼Ð¾ Ñ WhatsApp) ââ */
let FFMPEG_OK = null; /* ÐºÑÑ Ð´Ð¾ÑÑÑÐ¿Ð½Ð¾ÑÑÐ¸ ffmpeg Ð½Ð° ÑÑÐ¾Ð¹ Ð¼Ð°ÑÐ¸Ð½Ðµ (Railway: ÑÑÐ°Ð²Ð¸ÑÑÑ ÑÐµÑÐµÐ· nixpacks.toml) */
function ffmpegAvailable() {
  return new Promise((resolve) => {
    if (FFMPEG_OK !== null) return resolve(FFMPEG_OK);
    try { const p = spawn('ffmpeg', ['-version']); p.on('error', () => { FFMPEG_OK = false; resolve(false); }); p.on('close', (c) => { FFMPEG_OK = c === 0; resolve(FFMPEG_OK); }); }
    catch (_) { FFMPEG_OK = false; resolve(false); }
  });
}
/* Ð´Ð»Ð¸ÑÐµÐ»ÑÐ½Ð¾ÑÑÑ Ð²Ð¸Ð´ÐµÐ¾ â Ð¸Ð· stderr ÑÐ°Ð¼Ð¾Ð³Ð¾ ffmpeg (ffprobe Ð¼Ð¾Ð¶ÐµÑ Ð¾ÑÑÑÑÑÑÐ²Ð¾Ð²Ð°ÑÑ; ffmpeg Ð³Ð°ÑÐ°Ð½ÑÐ¸ÑÐ¾Ð²Ð°Ð½Ð½Ð¾ ÐµÑÑÑ) */
function ffprobeDuration(inPath) {
  return new Promise((resolve) => {
    let done = false; const fin = (v) => { if (!done) { done = true; resolve(v); } };
    try {
      const p = spawn('ffmpeg', ['-i', inPath]); let err = '';
      p.stderr.on('data', d => { err += d; if (err.length > 20000) err = err.slice(-20000); });
      p.on('error', () => fin(0));
      p.on('close', () => { const m = err.match(/Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)/); fin(m ? (+m[1]) * 3600 + (+m[2]) * 60 + parseFloat(m[3]) : 0); });
    } catch (_) { fin(0); }
  });
}
/* ÑÐ¶Ð°ÑÑ Ð´Ð¾ ~targetMB: Ð±Ð¸ÑÑÐµÐ¹Ñ Ð¸Ð· Ð´Ð»Ð¸ÑÐµÐ»ÑÐ½Ð¾ÑÑÐ¸, downscale â¤1280px, mp4 H.264 + AAC + faststart */
async function compressVideoToMp4(inPath, outPath, targetMB = 24) {
  const dur = await ffprobeDuration(inPath);
  const audioKbps = 96;
  let vKbps = dur > 0 ? Math.floor((targetMB * 1024 * 8) / dur) - audioKbps : 2500;
  vKbps = Math.max(400, Math.min(6000, vKbps));
  const args = ['-y', '-i', inPath, '-vf', "scale='min(1280,iw)':-2", '-c:v', 'libx264', '-preset', 'veryfast', '-b:v', vKbps + 'k', '-maxrate', Math.round(vKbps * 1.45) + 'k', '-bufsize', Math.round(vKbps * 2) + 'k', '-c:a', 'aac', '-b:a', audioKbps + 'k', '-movflags', '+faststart', outPath];
  await new Promise((resolve, reject) => {
    const p = spawn('ffmpeg', args); let err = '';
    p.stderr.on('data', d => { err += d; if (err.length > 4000) err = err.slice(-4000); });
    p.on('error', reject);
    p.on('close', (code) => code === 0 ? resolve() : reject(new Error('ffmpeg exit ' + code + ': ' + err.slice(-200))));
  });
  return outPath;
}

/* ââ Ð£ÐÐÐ«Ð Ð¢Ð ÐÐÐ¡ÐÐ ÐÐÐÐ¢ÐÐ  ÐºÑÐµÐ°ÑÐ¸Ð²Ð¾Ð²: Ð²Ð¸Ð´ÐµÐ¾ â Ð°ÑÐ´Ð¸Ð¾ (ffmpeg) â Gemini ÑÑÐ°Ð½ÑÐºÑÐ¸Ð¿Ñ â ÐºÐ¾Ð½ÑÐµÐºÑÑ Ð´Ð»Ñ Ð¿ÐµÑÑÐ¾Ð½Ð°Ð»Ð¸Ð·Ð°ÑÐ¸Ð¸ ââ */
function extractAudioMp3(inPath, outPath, maxSec = 300) {
  return new Promise((resolve, reject) => {
    const args = ['-y', '-i', inPath, '-vn', '-ac', '1', '-ar', '16000', '-b:a', '48k', '-t', String(maxSec), outPath];
    const pr = spawn('ffmpeg', args); let err = '';
    pr.stderr.on('data', d => { err += d; if (err.length > 3000) err = err.slice(-3000); });
    pr.on('error', reject);
    pr.on('close', c => c === 0 ? resolve(outPath) : reject(new Error('ffmpeg audio ' + c)));
  });
}
/* ÑÑÐ°Ð½ÑÐºÑÐ¸Ð¿Ñ Ð¾Ð·Ð²ÑÑÐºÐ¸ Ð²Ð¸Ð´ÐµÐ¾ ÑÐµÑÐµÐ· Gemini (Ð°ÑÐ´Ð¸Ð¾-Ð²ÑÐ¾Ð´). ÐÐ¾Ð·Ð²ÑÐ°Ñ {ok,text} Ð¸Ð»Ð¸ {ok:false,error}. */
async function transcribeCreativeVideo(videoAbsPath) {
  const key = process.env.GEMINI_API_KEY || '';
  if (!key) return { ok: false, error: 'no_gemini_key' };
  const audioPath = videoAbsPath + '.tr.mp3';
  try {
    await extractAudioMp3(videoAbsPath, audioPath);
    const b64 = fs.readFileSync(audioPath).toString('base64');
    if (b64.length > 18e6) return { ok: false, error: 'audio_too_long' };
    const prompt = 'Ð­ÑÐ¾ Ð¾Ð·Ð²ÑÑÐºÐ° ÑÐµÐºÐ»Ð°Ð¼Ð½Ð¾Ð³Ð¾ Ð²Ð¸Ð´ÐµÐ¾ Ð¾ Ð½ÐµÐ´Ð²Ð¸Ð¶Ð¸Ð¼Ð¾ÑÑÐ¸. Ð¢ÑÐ°Ð½ÑÐºÑÐ¸Ð±Ð¸ÑÑÐ¹ ÑÐµÑÑ ÐÐÐ¡ÐÐÐÐÐ Ð½Ð° ÑÐ·ÑÐºÐµ Ð¾ÑÐ¸Ð³Ð¸Ð½Ð°Ð»Ð°. ÐÐµÑÐ½Ð¸ Ð¢ÐÐÐ¬ÐÐ ÑÐµÐºÑÑ ÑÑÐ°Ð½ÑÐºÑÐ¸Ð¿ÑÐ°, Ð±ÐµÐ· Ð¿Ð¾ÑÑÐ½ÐµÐ½Ð¸Ð¹ Ð¸ ÑÐ°Ð¹Ð¼ÐºÐ¾Ð´Ð¾Ð². ÐÑÐ»Ð¸ ÑÐµÑÐ¸ Ð½ÐµÑ â Ð²ÐµÑÐ½Ð¸ Â«(Ð±ÐµÐ· ÑÐµÑÐ¸)Â».';
    const body = { contents: [{ parts: [{ text: prompt }, { inline_data: { mime_type: 'audio/mp3', data: b64 } }] }], generationConfig: { temperature: 0, maxOutputTokens: 2000 } };
    const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${key}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), signal: AbortSignal.timeout(90000) });
    const j = await r.json().catch(() => null);
    if (!r.ok) return { ok: false, error: 'gemini http ' + r.status + (j && j.error ? ' ' + (j.error.message || '').slice(0, 80) : '') };
    const parts = j && j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts;
    const text = parts ? parts.map(p => p.text || '').join('').trim() : '';
    return text ? { ok: true, text } : { ok: false, error: 'empty' };
  } catch (e) { return { ok: false, error: e.message }; }
  finally { try { fs.unlinkSync(audioPath); } catch (_) {} }
}
/* ÑÐ¾Ð½Ð¾Ð²ÑÐ¹ Ð¿ÑÐ¾Ð³Ð¾Ð½: ÑÑÐ°Ð²Ð¸Ñ ÑÑÐ°ÑÑÑ, ÑÑÐ°Ð½ÑÐºÑÐ¸Ð±Ð¸ÑÑÐµÑ, ÐºÐ»Ð°Ð´ÑÑ Ð½Ð° Ð¾Ð±ÑÑÐ²Ð»ÐµÐ½Ð¸Ðµ (+Ð¾Ð´Ð½Ð¾Ð¸Ð¼ÑÐ½Ð½ÑÐµ), ÑÐ¾ÑÑÐ°Ð½ÑÐµÑ */
