  for (const [ip, set] of Object.entries(byIp)) if (set.size >= 2) findings.push({ kind: 'ip_multi', severity: 'high', ip, who: [...set].map(brokerName), text: `${set.size} ÑÐ°Ð·Ð½ÑÑ Ð°ÐºÐºÐ°ÑÐ½ÑÐ° ÑÐ°Ð±Ð¾ÑÐ°ÑÑ Ñ Ð¾Ð´Ð½Ð¾Ð³Ð¾ IP Ð¿ÑÑÐ¼Ð¾ ÑÐµÐ¹ÑÐ°Ñ` });
  /* 2) Ð¾Ð´Ð¸Ð½ Ð°ÐºÐºÐ°ÑÐ½Ñ â Ð½ÐµÑÐºÐ¾Ð»ÑÐºÐ¾ IP Ð¾Ð´Ð½Ð¾Ð²ÑÐµÐ¼ÐµÐ½Ð½Ð¾ (ÑÐ°ÑÑÐ°ÑÐµÐ½Ð½ÑÐ¹ Ð´Ð¾ÑÑÑÐ¿) */
