    if (/^(Ð¢Ð¾Ð¿ ÑÐ²ÑÐ·Ð¾Ðº|ÐÐ¸Ð½Ð°Ð¼Ð¸ÐºÐ°)/.test(s)) return `<div class="sec">${esc(s)}</div>`;
    if (s.startsWith('ÐÑÐºÑÑÑÑ CRM')) return '';
