/* blocks Ð¿Ð¾Ð´Ð±Ð¾ÑÐºÐ¸: Ð¸Ð· ÑÐ¾ÑÑÐ°Ð½ÑÐ½Ð½ÑÑ Ð¸Ð»Ð¸ ÑÐ¸Ð½ÑÐµÐ· Ð¸Ð· legacy custom */
function collBlocks(c) {
  if (Array.isArray(c.blocks) && c.blocks.length) return c.blocks;
  const cust = c.custom || {};
  const hid = cust.hidden || [];
  let ids = (c.propertyIds || []).slice();
  if (cust.order && cust.order.length) ids = cust.order.filter((x) => ids.includes(x)).concat(ids.filter((x) => !cust.order.includes(x)));
  const b = [];
  b.push({ id: 'b_cover', t: 'cover', v: 'blue', data: {} });
  b.push({ id: 'b_hello', t: 'hello', v: 'std', hidden: hid.includes('hello'), data: {} });
  b.push({ id: 'b_sep', t: 'sep', v: 'blue', hidden: hid.includes('sep'), data: {} });
  /* ÑÐµÑÐµÐ´ÑÐµÐ¼ Ð²Ð°ÑÐ¸Ð°Ð½ÑÑ ÐºÐ°ÑÑÐ¾ÑÐµÐº Ð¾Ð±ÑÐµÐºÑÐ¾Ð² â ÑÐ¾ÑÐµÐ´Ð½Ð¸Ðµ Ð¿ÑÐ¾ÐµÐºÑÑ Ð²ÑÐ³Ð»ÑÐ´ÑÑ Ð¿Ð¾-ÑÐ°Ð·Ð½Ð¾Ð¼Ñ (Ð½Ðµ Â«Ð²ÑÑ fullÂ») */
  const projVars = ['full', 'gallery', 'full', 'compact'];
  ids.forEach((pid, i) => {
    const ov = (cust.props || {})[pid] || {};
    b.push({ id: 'b_p_' + pid, t: 'proj', v: (ov.v || projVars[i % projVars.length]), data: { pid, hookTitle: ov.hookTitle || '', blurb: ov.blurb || '', whyRent: ov.whyRent || null } });
  });
  b.push({ id: 'b_cta', t: 'cta', v: 'blue', hidden: hid.includes('cta'), data: {} });
  b.push({ id: 'b_why', t: 'why', v: 'std', hidden: hid.includes('why'), data: {} });
  b.push({ id: 'b_final', t: 'final', v: 'blue', hidden: hid.includes('final'), data: {} });
  return b;
}

/* ÑÐ°Ð½Ð¸ÑÐ°Ð¹Ð· Ð²ÑÐ±Ð¾ÑÐ° ÑÐ½Ð¸ÑÐ¾Ð² Ð¿Ð¾Ð´Ð±Ð¾ÑÐºÐ¸: {pid: [Ð¸Ð½Ð´ÐµÐºÑÑ]} â ÑÐ¾Ð»ÑÐºÐ¾ Ð²Ð°Ð»Ð¸Ð´Ð½ÑÐµ pid, ÑÐµÐ»ÑÐµ Ð¸Ð½Ð´ÐµÐºÑÑ â¥0, Ð´ÐµÐ´ÑÐ¿ */
function sanitizeUnitSel(raw, propertyIds) {
  if (!raw || typeof raw !== 'object') return {};
  const allow = new Set(propertyIds || []);
  const out = {};
  for (const pid of Object.keys(raw)) {
    if (!allow.has(pid)) continue;
    const arr = Array.isArray(raw[pid]) ? raw[pid] : [];
    const idx = [...new Set(arr.map(n => parseInt(n, 10)).filter(n => Number.isInteger(n) && n >= 0 && n < 400))].slice(0, 120);
    if (idx.length) out[pid] = idx;   /* Ð¿ÑÑÑÐ¾Ð¹ Ð²ÑÐ±Ð¾Ñ = Ð²ÑÐµ ÑÐ½Ð¸ÑÑ, ÐºÐ»ÑÑ Ð½Ðµ ÑÑÐ°Ð½Ð¸Ð¼ */
  }
  return out;
}

/* ÑÐ°Ð½Ð¸ÑÐ°Ð¹Ð· blocks Ð¿ÑÐ¸ ÑÐ¾ÑÑÐ°Ð½ÐµÐ½Ð¸Ð¸ Ð¸Ð· ÑÐµÐ´Ð°ÐºÑÐ¾ÑÐ° */
function sanitizeBlocks(raw) {
  if (!Array.isArray(raw)) return null;
  const okUrl = (s) => /^(assets\/|\/assets\/|https?:\/\/)/.test(s);
  const str = (s, n) => String(s == null ? '' : s).slice(0, n);
  const out = [];
  for (const b of raw.slice(0, 60)) {
    if (!b || !PB_TYPES[b.t]) continue;
    const meta = PB_TYPES[b.t];
    const nb = {
      id: /^[\w-]{1,40}$/.test(String(b.id)) ? String(b.id) : 'b_' + crypto.randomBytes(4).toString('hex'),
      t: b.t,
      v: meta.variants.includes(b.v) ? b.v : meta.variants[0],
      hidden: !!b.hidden,
      data: {},
    };
    const d = b.data || {};
    const put = (k, n) => { if (d[k] != null && String(d[k]).trim() !== '') nb.data[k] = str(d[k], n); };
    const putImg = (k) => { const v2 = str(d[k], 500).trim(); if (v2 && okUrl(v2)) nb.data[k] = v2; };
    const putList = (k, map) => { if (Array.isArray(d[k])) nb.data[k] = d[k].slice(0, 20).map(map).filter(Boolean); };
    put('title', 300); put('sub', 500); put('body', 4000); put('caption', 400);
    put('heading', 300); put('text', 2000); put('author', 120); put('role', 200);
    put('intro', 2000); put('badge', 120); put('btn', 80); put('freeNote', 400);
    put('hookTitle', 200); put('blurb', 800); put('officeText', 800);
    put('lede', 200); put('aboutHeading', 200); put('recTitle', 200); put('brandName', 120); put('note', 400);
    putImg('img'); putImg('photo');
    /* ÑÑÑÐ½Ð¾Ð¹ ÑÐµÑÐ°Ð¹Ð·/ÑÐ¾ÐºÑÑ ÐºÐ°ÑÑÐ¸Ð½Ð¾Ðº ÐºÐ¾Ð½ÑÑÑÑÐºÑÐ¾ÑÐ°: Ð²ÑÑÐ¾ÑÐ° Ð¸ ÑÐ¾ÑÐºÐ° ÑÐ¾ÐºÑÑÐ° ÑÐ¾Ð½Ð° */
    const num = (k, lo, hi) => { if (d[k] != null && d[k] !== '') { const n = Math.max(lo, Math.min(hi, Math.round(+d[k]))); if (!isNaN(n)) nb.data[k] = n; } };
    num('imgH', 80, 1400); num('imgFx', 0, 100); num('imgFy', 0, 100);
    if (b.t === 'video') { const v2 = str(d.url, 500).trim(); if (v2 && /^(assets\/|\/assets\/|https?:\/\/)/.test(v2)) nb.data.url = v2; }
    if (b.t === 'proj') { nb.data.pid = str(d.pid, 30); putList('imgs', (x) => { const s2 = str(x, 500).trim(); return s2 && okUrl(s2) ? s2 : null; }); putList('whyRent', (x) => str(x, 300).trim() || null); }
    if (b.t === 'gallery') putList('imgs', (x) => { const s2 = str(x, 500).trim(); return s2 && okUrl(s2) ? s2 : null; });
    if (b.t === 'stats') putList('items', (x) => x && (x.k || x.v) ? { k: str(x.k, 120), v: str(x.v, 60) } : null);
    if (b.t === 'faq') putList('items', (x) => x && (x.q || x.a) ? { q: str(x.q, 300), a: str(x.a, 1000) } : null);
    if (b.t === 'steps' || b.t === 'benefits') putList('items', (x) => x && (x.title || x.text) ? { icon: str(x.icon, 20), title: str(x.title, 200), text: str(x.text, 600) } : null);
    if (b.t === 'compare') { put('headA', 120); put('headB', 120); putList('items', (x) => x && (x.k || x.a || x.b) ? { k: str(x.k, 160), a: str(x.a, 200), b: str(x.b, 200) } : null); }
    if (b.t === 'timeline') putList('items', (x) => x && (x.when || x.title) ? { when: str(x.when, 80), title: str(x.title, 200), text: str(x.text, 500) } : null);
    if (b.t === 'pricecards') putList('items', (x) => x && (x.name || x.price) ? { name: str(x.name, 120), price: str(x.price, 80), text: str(x.text, 600) } : null);
    if (b.t === 'team') putList('items', (x) => x && (x.name || x.role) ? { name: str(x.name, 120), role: str(x.role, 200) } : null);
    if (b.t === 'amenities') putList('items', (x) => x && (x.icon || x.label) ? { icon: str(x.icon, 20), label: str(x.label, 120) } : null);
    if (b.t === 'guarantee') putList('items', (x) => x && (x.icon || x.title || x.text) ? { icon: str(x.icon, 20), title: str(x.title, 200), text: str(x.text, 600) } : null);
    if (b.t === 'hero') { put('heading', 200); put('sub', 400); }
    if (b.t === 'bignum') { put('v', 60); put('k', 300); }
    if (b.t === 'hello' || b.t === 'why' || b.t === 'checklist') putList('bullets', (x) => str(x, 400).trim() || null);
    if (b.t === 'cta') { const h = str(d.href, 500).trim(); if (h && /^(https?:\/\/|mailto:|tel:)/.test(h)) nb.data.href = h; }
    out.push(nb);
  }
  return out.length ? out : null;
}


/* mime â ÑÐ°ÑÑÐ¸ÑÐµÐ½Ð¸Ðµ ÑÐ°Ð¹Ð»Ð° (Ð´Ð»Ñ ÑÐ¾ÑÑÐ°Ð½ÐµÐ½Ð¸Ñ Ð²ÑÐ¾Ð´ÑÑÐ¸Ñ Ð¼ÐµÐ´Ð¸Ð° WhatsApp) */
function mimeToExt(mime) {
  const m = String(mime || '').split(';')[0].trim().toLowerCase();
  const MAP = {
    'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
    'video/mp4': 'mp4', 'video/3gpp': '3gp', 'video/quicktime': 'mov', 'video/webm': 'webm',
    'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac', 'audio/amr': 'amr', 'audio/wav': 'wav',
    'application/pdf': 'pdf', 'application/zip': 'zip', 'text/plain': 'txt', 'text/csv': 'csv',
    'application/msword': 'doc', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
    'application/vnd.ms-excel': 'xls', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  };
  if (MAP[m]) return MAP[m];
  const sub = m.split('/')[1];
  return sub ? sub.replace(/[^a-z0-9]/g, '').slice(0, 5) : '';
}

/* SEC: Ð¿ÑÐ¾ÑÑÐ¾Ð¹ in-memory Ð»Ð¸Ð¼Ð¸ÑÐµÑ (single-instance launchd) â Ð¾ÐºÐ½Ð¾ ÑÐºÐ¾Ð»ÑÐ¶ÐµÐ½Ð¸Ñ Ð¿Ð¾ ÐºÐ»ÑÑÑ */
const _rlMap = new Map();
function rateHit(key, max, windowMs) {
  const now = Date.now(); const e = _rlMap.get(key);
  if (!e || now - e.t > windowMs) { _rlMap.set(key, { t: now, n: 1 }); return true; }
  if (e.n >= max) return false; e.n++; return true;
}

/* SEC: Ð±ÐµÐ·Ð¾Ð¿Ð°ÑÐ½ÑÐ¹ Ð¿ÑÑÑ Ðº Ð°ÑÑÐµÑÑ â ÑÐµÐ·Ð¾Ð»Ð²Ð¸Ð¼ Ð¸ Ð¿ÑÐ¾Ð²ÐµÑÑÐµÐ¼, ÑÑÐ¾ Ð¾Ð½ ÐÐÐ£Ð¢Ð Ð assets (Ð·Ð°ÑÐ¸ÑÐ° Ð¾Ñ ../ traversal).
   ÐÐ°Ð³ÑÑÐ·ÐºÐ¸ Ð»ÐµÐ¶Ð°Ñ Ð½Ð° ÑÐ¾Ð¼Ðµ (UPLOADS_DIR) â ÑÐ¿ÐµÑÐ²Ð° Ð¿ÑÐ¾Ð²ÐµÑÑÐµÐ¼ ÑÐ¾Ð¼, Ð¸Ð½Ð°ÑÐµ ÐºÐ¾Ð¼Ð¼Ð¸ÑÐ½ÑÑÑÑ ÑÑÐ°ÑÐ¸ÐºÑ public/assets. */
function assetPathSafe(webPath) {
  const rel = String(webPath || '').replace(/^\/+/, '');
  for (const base of [UPLOADS_DIR, path.resolve(PUBLIC, 'assets')]) {
    const abs = path.resolve(base, rel.replace(/^assets\//, ''));
    if ((abs === base || abs.startsWith(base + path.sep)) && fs.existsSync(abs)) return abs;
  }
  return null;
}

/* --- Ð·Ð°Ð¿Ð¸ÑÑ Ð·Ð²Ð¾Ð½ÐºÐ° â ÑÐºÐ°ÑÐ°ÑÑ â Whisper â ÑÑÐ°Ð½ÑÐºÑÐ¸Ð¿Ñ Ð² ÐºÐ°ÑÑÐ¾ÑÐºÑ Ð»Ð¸Ð´Ð° (Ð¾Ð±ÑÐ°Ñ Ð´Ð»Ñ Ð²ÑÐµÑ Ð¿ÑÐ¾Ð²Ð°Ð¹Ð´ÐµÑÐ¾Ð²) --- */
function ingestCallRecording(db, lead, recUrl, label, durSec, authHeader) {
  (async () => {
    try {
      const r2 = await fetch(recUrl, authHeader ? { headers: { Authorization: authHeader } } : undefined);
      if (!r2.ok) throw new Error('Ð·Ð°Ð¿Ð¸ÑÑ Ð½ÐµÐ´Ð¾ÑÑÑÐ¿Ð½Ð°: ' + r2.status);
      const buf = Buffer.from(await r2.arrayBuffer());
      if (buf.length > 24e6) throw new Error('Ð·Ð°Ð¿Ð¸ÑÑ Ð±Ð¾Ð»ÑÑÐµ 24ÐÐ');
      const extM = String(recUrl).split('?')[0].match(/\.(flac|m4a|mp3|mp4|mpeg|mpga|oga|ogg|wav|webm)$/i);
      const ext = extM ? extM[1].toLowerCase() : 'mp3';
      /* 1) ÑÐ¾ÑÑÐ°Ð½ÑÐµÐ¼ ÐÐ ÐÐÐÐ Ð«ÐÐÐÐÐ£Ð® Ð·Ð°Ð¿Ð¸ÑÑ Ð² ÐºÐ°ÑÑÐ¾ÑÐºÑ (Ð³Ð¾Ð»Ð¾ÑÐ¾Ð²Ð¾Ð¹) â ÑÐ°Ð½ÑÑÐµ ÑÐ¾ÑÑÐ°Ð½ÑÐ»ÑÑ ÑÐ¾Ð»ÑÐºÐ¾ ÑÐµÐºÑÑ */
      let audioUrl = null; try { const saved = tgbridge.saveMedia(buf, ext); audioUrl = saved && saved.url; } catch (e) {}
      /* 2) ÑÑÐ°Ð½ÑÐºÑÐ¸Ð¿Ñ (Whisper, Ð°Ð²ÑÐ¾-Ð´ÐµÑÐµÐºÑ ÑÐ·ÑÐºÐ°) */
      const text = String(await llm.transcribe(buf, 'call.' + ext) || '').trim();
      lead.transcripts = lead.transcripts || [];
      lead.transcripts.push({ id: store.nextId('tr'), at: Date.now(), label: (label || 'ÐÐ²Ð¾Ð½Ð¾Ðº') + (durSec ? ' Â· ' + durSec + 'Ñ' : ''), text: text.slice(0, 20000), audio: audioUrl || null });
      if (audioUrl) { lead.voiceNotes = lead.voiceNotes || []; lead.voiceNotes.unshift({ id: crypto.randomBytes(4).toString('hex'), url: audioUrl, dur: durSec || 0, transcript: text.slice(0, 4000), who: label || 'ÐÐ²Ð¾Ð½Ð¾Ðº', at: Date.now() }); }
      ai.pushEvent(db, { type: 'call', leadId: lead.id, text: `ÐÐ²Ð¾Ð½Ð¾Ðº Ð·Ð°Ð¿Ð¸ÑÐ°Ð½ Ð¸ ÑÐ°ÑÑÐ¸ÑÑÐ¾Ð²Ð°Ð½ (${text.length} ÑÐ¸Ð¼Ð².)` });
      store.save();
      /* 3) ÐÐÐ¢Ð-ÐÐÐÐÐÐ: ÐÐ-ÑÐ²Ð¾Ð´ÐºÐ° ÑÑÐ°Ð·Ñ Ð¿Ð¾ ÑÐ²ÐµÐ¶ÐµÐ¼Ñ ÑÑÐ°Ð½ÑÐºÑÐ¸Ð¿ÑÑ (ÑÐ°Ð½ÑÑÐµ Ð¿ÑÐ¸ÑÐ¾Ð´Ð¸Ð»Ð¾ÑÑ Ð¶Ð°ÑÑ Ð²ÑÑÑÐ½ÑÑ) */
      if (text && llm.available()) { try { const sum = await llm.summarize(db, lead); if (sum) { lead.summary = sum; lead.summaryAt = Date.now(); ai.pushEvent(db, { type: 'call', leadId: lead.id, text: 'ÐÐ Ð¾Ð±Ð½Ð¾Ð²Ð¸Ð» ÑÐ²Ð¾Ð´ÐºÑ Ð¿Ð¾ Ð»Ð¸Ð´Ñ Ð¿Ð¾ÑÐ»Ðµ Ð·Ð²Ð¾Ð½ÐºÐ°' }); store.save(); } } catch (e) { console.error('[call-summary]', e.message); } }
      /* 4) ÐÐÐ¡Ð¢-ÐÐÐÐÐÐÐÐÐ¯ Ð ÐÐÐÐÐÐÐ: ÑÑÐ°Ð½ÑÐºÑÐ¸Ð¿Ñ + Ð¿ÑÐ¸ÑÐ¾-Ð¿Ð°ÑÑÐµÑÐ½Ñ â Ð³Ð¾ÑÐ¾Ð²Ð¾Ðµ Ð¿ÐµÑÐ²Ð¾Ðµ ÐºÐ°ÑÐ°Ð½Ð¸Ðµ Ð² WhatsApp
         (Ð´Ð¾Ð·Ð²Ð¾Ð½ = ÐµÑÑÑ ÑÑÐ°Ð½ÑÐºÑÐ¸Ð¿Ñ). ÐÐ»Ð°Ð´ÑÐ¼ Ð§ÐÐ ÐÐÐÐÐ Ð² lead.postCall â Ð±ÑÐ¾ÐºÐµÑ Ð¾ÑÐ¿ÑÐ°Ð²Ð¸Ñ ÐµÐ³Ð¾ ÑÐµÑÑÐ¼ ÑÐ¿Ð¾ÑÐ¾Ð±Ð¾Ð¼
         ÑÐ¾ ÑÐ²Ð¾ÐµÐ³Ð¾ Ð¿ÑÐ¾Ð³ÑÐµÑÐ¾Ð³Ð¾ Ð½Ð¾Ð¼ÐµÑÐ° (ÐºÐ½Ð¾Ð¿ÐºÐ° Ð² ÐºÐ°ÑÑÐ¾ÑÐºÐµ), Ð° Ð½Ðµ Ð°Ð²ÑÐ¾ÑÐ»ÑÑ. ÐÐµÐ´Ð¾Ð·Ð²Ð¾Ð½ (Ð½ÐµÑ Ð·Ð°Ð¿Ð¸ÑÐ¸) ÑÑÐ´Ð° Ð½Ðµ
         Ð¿Ð¾Ð¿Ð°Ð´Ð°ÐµÑ â ÑÐ°Ð¼ ÑÐ°Ð±Ð¾ÑÐ°ÐµÑ Ð¾Ð±ÑÑÐ½Ð°Ñ ÑÐµÐºÑÑÐ¾Ð²Ð°Ñ ÑÐµÐ¿Ð¾ÑÐºÐ° ÐºÐ°ÑÐ°Ð½Ð¸Ð¹ Ð´Ð²Ð¸Ð¶ÐºÐ°. */
      if (text && text.length > 40 && llm.available()) {
        try {
          const pc = await llm.composePostCall(db, lead, db.settings.agency.name);
          if (pc && pc.message) {
            lead.postCall = { message: pc.message, approach: pc.approach, sendSelection: !!pc.sendSelection, reason: pc.reason, at: Date.now(), sent: false };
            const apRu = { selection: 'Ð¿Ð¾Ð´Ð±Ð¾ÑÐºÐ° ÑÑÐ°Ð·Ñ', warmup: 'Ð¼ÑÐ³ÐºÐ¸Ð¹ Ð¿ÑÐ¾Ð³ÑÐµÐ²', connect: 'Ð·Ð°ÐºÑÐµÐ¿Ð¸ÑÑÑÑ Ð² Ð¼ÐµÑÑÐµÐ½Ð´Ð¶ÐµÑÐµ' }[pc.approach] || pc.approach;
            ai.pushEvent(db, { type: 'call', leadId: lead.id, text: `ÐÐ Ð¿Ð¾Ð´Ð³Ð¾ÑÐ¾Ð²Ð¸Ð» ÐºÐ°ÑÐ°Ð½Ð¸Ðµ Ð¿Ð¾ÑÐ»Ðµ Ð·Ð²Ð¾Ð½ÐºÐ° (${apRu}) â Ð¿ÑÐ¾Ð²ÐµÑÑÑÐµ Ð¸ Ð¾ÑÐ¿ÑÐ°Ð²ÑÑÐµ` });
            store.save();
          }
        } catch (e) { console.error('[post-call]', e.message); }
      }
    } catch (e) { console.error('[call-ingest]', e.message); }
  })();
}

