        const conn = (g.numbers || []).map(n => ({ n, real: (live[tgGraySid(n.phone)] || {}).phone, status: (live[tgGraySid(n.phone)] || {}).status })).filter(x => x.status === 'connected' && /^\d{7,15}$/.test(String(x.real || '')));
        if (conn.length < 2) return;
