    const r = await meetingBot.scheduleBot(mt.link, mt.at, { meetingId: mt.id, leadId: mt.leadId, tid: store.currentTid() });
    if (r.ok) { mt.botId = r.botId; mt.transcriptStatus = 'scheduled'; }
