/* --- Telegram Mini App: Ð²Ð°Ð»Ð¸Ð´Ð°ÑÐ¸Ñ initData (Ð¿Ð¾Ð´Ð¿Ð¸ÑÑ Telegram bot-token'Ð¾Ð¼) --- */
function tgValidateInitData(initData, botToken) {
  if (!initData || !botToken) return null;
  const params = new URLSearchParams(initData);
  const hash = params.get('hash'); if (!hash) return null;
  params.delete('hash');
  const dcs = [...params.entries()].map(([k, v]) => `${k}=${v}`).sort().join('\n');
  const secret = crypto.createHmac('sha256', 'WebAppData').update(botToken).digest();
  const calc = crypto.createHmac('sha256', secret).update(dcs).digest('hex');
  if (calc.length !== hash.length || !crypto.timingSafeEqual(Buffer.from(calc), Buffer.from(hash))) return null;
  const authDate = +params.get('auth_date') || 0;
  if (authDate && Date.now() / 1000 - authDate > 86400) return null;   /* initData ÑÑÐ°ÑÑÐµ ÑÑÑÐ¾Ðº â Ð½Ðµ Ð¿ÑÐ¸Ð½Ð¸Ð¼Ð°ÐµÐ¼ */
  try { return JSON.parse(params.get('user') || 'null'); } catch { return null; }
}
/* Ð±ÑÐ¾ÐºÐµÑ, Ð¾ÑÐºÑÑÐ²ÑÐ¸Ð¹ Ð¼Ð¸Ð½Ð¸-Ð°Ð¿Ð¿ (Ð¿Ð¾ Telegram user.id â broker.tgChatId) */
function tgAppBroker(req, db) {
  const user = tgValidateInitData(req.headers['x-tg-init-data'] || '', tgbridge.token(db));
  if (!user || !user.id) return null;
  return db.brokers.find(b => String(b.tgChatId) === String(user.id) && b.active !== false) || null;
}
/* ÑÐ¾Ð»Ñ Ð¿Ð¾Ð»ÑÐ·Ð¾Ð²Ð°ÑÐµÐ»Ñ Ð¼Ð¸Ð½Ð¸-Ð°Ð¿Ð¿Ð°: Ð±ÑÐ¾ÐºÐµÑ (Ð¿Ð¾ tgChatId) ÐÐÐ Ð¾ÑÐ½Ð¾Ð²Ð°ÑÐµÐ»Ñ (Ð¿Ð¾ settings.ownerTgChatId).
   ÐÑÐ¾ÐºÐµÑÑÐºÐ°Ñ ÑÐµÐ·Ð¾Ð»ÑÑÐ¸Ñ Ð¸Ð´ÐµÐ½ÑÐ¸ÑÐ½Ð° tgAppBroker â ÑÑÑÐµÑÑÐ²ÑÑÑÐ¸Ð¹ Ð¿ÑÑÑ Ð½Ðµ Ð¼ÐµÐ½ÑÐµÑÑÑ. */
function tgAppUser(req, db) {
  const user = tgValidateInitData(req.headers['x-tg-init-data'] || '', tgbridge.token(db));
  if (!user || !user.id) return null;
  const broker = db.brokers.find(b => String(b.tgChatId) === String(user.id) && b.active !== false);
  if (broker) return { role: 'broker', broker };
  if (db.settings.ownerTgChatId && String(db.settings.ownerTgChatId) === String(user.id)) return { role: 'owner' };
  return null;
}

