    /* ÐÐ ÐÐÐÐ ÐÐ ICS-ÑÑÑÐ»ÐºÐ¸ ÐºÐ°Ð»ÐµÐ½Ð´Ð°ÑÑ Ð±ÑÐ¾ÐºÐµÑÐ°: ÑÑÐ½ÐµÐ¼, Ð¿Ð°ÑÑÐ¸Ð¼, Ð¾ÑÐ´Ð°ÑÐ¼ Â«Ð½Ð°ÑÐ»Ð¸ N ÑÐ¾Ð±ÑÑÐ¸Ð¹, Ð±Ð»Ð¸Ð¶Ð°Ð¹ÑÐµÐµ Ð·Ð°Ð½ÑÑÐ¾Ðµ Ð¾ÐºÐ½Ð¾Â».
       ÐÐµÐ»Ð°ÐµÑ Ð¿Ð¾Ð´ÐºÐ»ÑÑÐµÐ½Ð¸Ðµ Ð´ÑÑÐ°ÐºÐ¾ÑÑÑÐ¾Ð¹ÑÐ¸Ð²ÑÐ¼ â Ð±ÑÐ¾ÐºÐµÑ ÑÑÐ°Ð·Ñ Ð²Ð¸Ð´Ð¸Ñ, Ð²ÐµÑÐ½ÑÑ Ð»Ð¸ ÑÑÑÐ»ÐºÑ Ð²ÑÑÐ°Ð²Ð¸Ð». */
    if ((tgm = p.match(/^\/api\/brokers\/([^/]+)\/ics-test$/)) && req.method === 'POST') {
      if (!getSession(req)) return json(res, 401, { error: 'auth' });
      const br = db.brokers.find(x => x.id === tgm[1]); if (!br) return json(res, 404, { error: 'not found' });
      const b = await readBody(req);
      const url = String((b && b.url) || br.busyIcsUrl || '').trim();
      if (!url) return json(res, 400, { error: 'Ð½ÐµÑ ÑÑÑÐ»ÐºÐ¸' });
      if (!/^https?:\/\//i.test(url)) return json(res, 200, { ok: false, reason: 'Ð¡ÑÑÐ»ÐºÐ° Ð´Ð¾Ð»Ð¶Ð½Ð° Ð½Ð°ÑÐ¸Ð½Ð°ÑÑÑÑ Ñ http(s)://' });
      try {
        const { text } = await safeFetch(url);
        if (!/BEGIN:VCALENDAR/i.test(text)) return json(res, 200, { ok: false, reason: 'ÐÐ¾ ÑÑÑÐ»ÐºÐµ Ð½ÐµÑ ÐºÐ°Ð»ÐµÐ½Ð´Ð°ÑÑ (Ð½ÐµÑ BEGIN:VCALENDAR). ÐÑÐ¾Ð²ÐµÑÑÑÐµ, ÑÑÐ¾ ÑÑÐ¾ Ð¿ÑÑÐ¼Ð°Ñ ICS-ÑÑÑÐ»ÐºÐ°.' });
        const iv = parseIcsBusy(text);
        const now = Date.now();
        const next = iv.filter(x => x.e > now).sort((a, c) => a.s - c.s)[0] || null;
        const fmt = t => new Date(t).toLocaleString('ru-RU', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
        return json(res, 200, { ok: true, count: iv.length, next: next ? { from: fmt(next.s), to: fmt(next.e) } : null });
      } catch (e) { return json(res, 200, { ok: false, reason: 'ÐÐµ ÑÐ´Ð°Ð»Ð¾ÑÑ Ð·Ð°Ð³ÑÑÐ·Ð¸ÑÑ ÑÑÑÐ»ÐºÑ: ' + (e.message || 'Ð¾ÑÐ¸Ð±ÐºÐ° ÑÐµÑÐ¸') }); }
    }

