      if (p === '/api/admin/farm/number' && req.method === 'POST') { const b = await readBody(req).catch(() => ({})); if (!b.phone) return json(res, 400, { error: 'Ð½ÑÐ¶ÐµÐ½ Ð½Ð¾Ð¼ÐµÑ' }); const n = farmSvc.addNumber(b); adminLog('farm.number.add', { id: n.id, phone: n.phone }); return json(res, 200, { ok: true, number: n }); }
