        const fallback = db.brokers.filter(x => x.id !== br.id && x.active !== false).sort((a2, b2) => (a2.load || 0) - (b2.load || 0))[0];
        for (const mt of db.meetings || []) if (mt.brokerId === br.id && (!mt.status || !['done', 'cancelled', 'no_show'].includes(mt.status))) { const tgt = (successorId !== 'auto' && db.brokers.find(x => x.id === successorId && x.active !== false)) || fallback; if (tgt) mt.brokerId = tgt.id; }
        /* WhatsApp-Ð½Ð¾Ð¼ÐµÑ ÑÑÐµÐ´ÑÐµÐ³Ð¾ Ð±ÑÐ¾ÐºÐµÑÐ°: Ð¿ÐµÑÐµÐ´Ð°ÑÐ¼ Ð¿ÑÐµÐµÐ¼Ð½Ð¸ÐºÑ (ÐµÑÐ»Ð¸ Ð²ÑÐ±ÑÐ°Ð½ ÐºÐ¾Ð½ÐºÑÐµÑÐ½ÑÐ¹) + Ð¡ÐÐ ÐÐ¡ Ð¾ÑÐ¾ÑÐ¼Ð»ÐµÐ½Ð¸Ñ,
           ÑÑÐ¾Ð±Ñ Ð½Ð¾Ð²ÑÐ¹ Ð±ÑÐ¾ÐºÐµÑ Ð·Ð°Ð²ÑÐ» Ð¸Ð¼Ñ/Ð°Ð²Ð°ÑÐ°Ñ Ð·Ð°Ð½Ð¾Ð²Ð¾; ÑÐµÐ°Ð»ÑÐ½ÑÐ¹ Ð°ÐºÐºÐ°ÑÐ½Ñ ÑÐ¾Ð¶Ðµ ÑÐ±ÑÐ°ÑÑÐ²Ð°ÐµÐ¼ ÑÐµÑÐµÐ· Ð²Ð¾ÑÐºÐµÑ. */
        let numMoved = 0;
