        audit(db, req, `Ð¾ÑÑÐ±Ð¾ÑÐ´Ð¸Ð½Ð³: ${moved} Ð»Ð¸Ð´Ð¾Ð² Ð¿ÐµÑÐµÐ´Ð°Ð½Ð¾, Ð´Ð¾ÑÑÑÐ¿ Ð¾ÑÐ¾Ð·Ð²Ð°Ð½`, { broker: br.name, successor: successorId });
        ai.pushEvent(db, { type: 'handover', text: `ð¦ ÐÐµÑÐµÐ´Ð°ÑÐ° Ð´ÐµÐ»: ${br.name} Ð¾ÑÐºÐ»ÑÑÑÐ½, ${moved} Ð»Ð¸Ð´Ð¾Ð² Ð¿ÐµÑÐµÐ´Ð°Ð½Ñ ÐºÐ¾Ð¼Ð°Ð½Ð´Ðµ${b.notifyClients ? ' (ÐºÐ»Ð¸ÐµÐ½ÑÑ ÑÐ²ÐµÐ´Ð¾Ð¼Ð»ÐµÐ½Ñ)' : ''}` });
        store.save();
