        if (b.alertCooldownMin != null) c.alertCooldownMin = clamp(b.alertCooldownMin, 5, 1440, 30);
        if (b.alertRepeatH != null) c.alertRepeatH = clamp(b.alertRepeatH, 1, 336, 24);
        /* Ð´ÐµÐ»ÐµÐ³Ð¸ÑÐ¾Ð²Ð°Ð½Ð¸Ðµ ÐºÐ¾Ð½ÑÑÐ¾Ð»Ñ: ÑÐ¾Ð»ÑÐºÐ¾ Ð²Ð»Ð°Ð´ÐµÐ»ÐµÑ Ð¼Ð¾Ð¶ÐµÑ Ð¿ÐµÑÐµÐ´Ð°ÑÑ/Ð·Ð°Ð±ÑÐ°ÑÑ; broker-Ð´ÐµÐ»ÐµÐ³Ð°Ñ Ð½Ðµ Ð¼Ð¾Ð¶ÐµÑ Ð¿ÐµÑÐµÐ½Ð°Ð·Ð½Ð°ÑÐ¸ÑÑ ÑÐµÐ±Ñ Ð¶Ðµ */
