      const columns = t.header.map((h, i) => ({ idx: i, header: h || `ÐÐ¾Ð»Ð¾Ð½ÐºÐ° ${i + 1}`, samples: t.rows.slice(0, 3).map(r => String(r[i] || '').slice(0, 48)) }));
