      const defaults = b.defaults || {};
      /* Ð¼Ð°Ð¿Ð¿Ð¸Ð½Ð³ Ð¸Ð· Ð¼Ð°ÑÑÐµÑÐ° {Ð¿Ð¾Ð»Ðµ: Ð¸Ð½Ð´ÐµÐºÑÐÐ¾Ð»Ð¾Ð½ÐºÐ¸}; Ð½ÐµÑ â Ð°Ð²ÑÐ¾-ÑÐ³Ð°Ð´ÑÐ²Ð°Ð½Ð¸Ðµ (Ð¾Ð±ÑÐ°ÑÐ½Ð°Ñ ÑÐ¾Ð²Ð¼ÐµÑÑÐ¸Ð¼Ð¾ÑÑÑ Ñ Ð¿Ð°ÑÑÐ¾Ð¼) */
      let map = (b.mapping && typeof b.mapping === 'object') ? b.mapping : guessImportMapping(t.header);
