      const SG_SBAR = `<div class="s-tbar"><button data-sact="recompose" title="ÐÑÑÐ³Ð°Ñ ÐºÐ¾Ð¼Ð¿Ð¾Ð·Ð¸ÑÐ¸Ñ (Ð¡ÑÑÐ´Ð¸Ñ)">ð²</button><button data-sact="edit" title="Ð ÐµÐ´Ð°ÐºÑÐ¸ÑÐ¾Ð²Ð°ÑÑ">â</button><button data-sact="dup" title="ÐÑÐ±Ð»Ð¸ÑÐ¾Ð²Ð°ÑÑ">â§</button><button data-sact="up" title="ÐÑÑÐµ">â</button><button data-sact="down" title="ÐÐ¸Ð¶Ðµ">â</button><button data-sact="del" title="Ð£Ð´Ð°Ð»Ð¸ÑÑ">â</button></div><button class="s-ins" data-sact="insert" title="ÐÐ¾Ð±Ð°Ð²Ð¸ÑÑ ÑÐ»Ð°Ð¹Ð´ Ð¿Ð¾ÑÐ»Ðµ">ï¼ Ð¡Ð»Ð°Ð¹Ð´</button>`;
      /* â­ ÐÐÐ ÐÐÐÐÐ¦Ð ÐºÐ°Ðº first-class: Ñ Fraunces/Cormorant/Instrument/EB/Space Grotesk/Unbounded/Bebas ÐÐÐ¢ ÐºÐ¸ÑÐ¸Ð»Ð»Ð¸ÑÑ â
         RU-Ð·Ð°Ð³Ð¾Ð»Ð¾Ð²ÐºÐ¸ Ð¿Ð°Ð´Ð°Ð»Ð¸ Ð² Times (Â«bulkyÂ»). ÐÐµÑÐµÐºÑÐ¸Ð¼ ÐºÐ¸ÑÐ¸Ð»Ð»Ð¸ÑÑ Ð² ÑÐµÐºÑÑÐµ ÐºÐ¾Ð»Ð¾Ð´Ñ Ð¸ Ð¿Ð¾Ð´Ð¼ÐµÐ½ÑÐµÐ¼ Ð½Ð° ÑÑÐ¸ÑÑ Ñ ÐºÐ¸ÑÐ¸Ð»Ð»Ð¸ÑÐµÐ¹ ÑÐ¾Ð³Ð¾ Ð¶Ðµ ÑÐ°ÑÐ°ÐºÑÐµÑÐ°. */
      const FONT_CYR = new Set(['playfair', 'ptserif', 'manrope', 'inter', 'montser', 'oswald', 'russo', 'tektur', 'rusdisplay', 'comfortaa', 'caveat', 'badscript', 'neucha', 'pangolin', 'adventpro', 'robotocond']);
