      /* ÑÑÐµÐº Ñ ÐºÐ¸ÑÐ¸Ð»Ð»Ð¸ÑÐµÑÐºÐ¸Ð¼ ÑÐµÑÐ¸Ñ-ÑÐ¾Ð»Ð±ÑÐºÐ¾Ð¼, ÑÑÐ¾Ð±Ñ Ð»Ð°ÑÐ¸Ð½ÑÐºÐ¸Ð¹ Ð´Ð¸ÑÐ¿Ð»ÐµÐ¹-ÑÑÐ¸ÑÑ Ð½Ðµ ÑÐ¾Ð½ÑÐ» ÐºÐ¸ÑÐ¸Ð»Ð»Ð¸ÑÑ Ð² Times */
      const dispStack = hf.cat === 'sans' ? hf.fam.replace(/,sans-serif$/, ",'Manrope',sans-serif") : hf.fam.replace(/,(serif|cursive)$/, ",'PT Serif',serif");
