      const counter = ['frac', 'num', 'dot', 'roman', 'off'].includes(c.counter) ? c.counter : 'frac';
      const footerStyle = ['plain', 'pill', 'line', 'serif'].includes(footer.style) ? footer.style : 'plain';
      const footerHide = !!footer.hide;
