              const marks = (Array.isArray(s.pmarks) && s.pmarks.length) ? s.pmarks : null;   /* â­ Ð¿Ð¾-ÑÑÑÐ¾ÑÐ½ÑÐµ Ð¼Ð°ÑÐºÐµÑÑ */
